/// <summary>
///     The <c>AVASalesJournalChangeType_Extension</c> class is the extension for <c>SalesJournalChangeType</c>
/// </summary>
[ExtensionOf(classStr(SalesJournalChangeType))]
final class AVASalesJournalChangeType_Extension
{
}

Method.Source:
/// <summary>
/// AVA/WEN/2025/04/11 AVA_013179_IC_DlvDate
/// </summary>
public void  run()
{
    Set set = new Set(Types::String);
    SetEnumerator    setEnum;
    salesTable salesTableLocal;

    while (journal.next())
    {
        salesTable = journal.get(tableNum(SalesTable));
        set.add(salesTable.salesId);
        if (salesTable.InterCompanyDirectDelivery && salesTable.InterCompanyAutoCreateOrders)
        {
            salesTable.AVAupdateDlvDatesForICUpdate();
        }
    }

    journal.reset();

    next run();

    setEnum = set.getEnumerator();

    while (setEnum.moveNext())
    {
        salesTablelocal = salesTable::find(setEnum.current());
        if (salesTableLocal.SalesType == salesType::Sales)
        {
            salesTablelocal.AVAinterCompanyAutoCreateOrders();
        }
    }
}
